public class ObjectUtilsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("sameContent(\"java\", \"java\")", true, ObjectUtils.sameContent("java", "java"));
            check("sameContent(\"java\", \"JAVA\")", false, ObjectUtils.sameContent("java", "JAVA"));
            check("sameContent(null, null)", true, ObjectUtils.sameContent(null, null));
            check("sameContent(\"x\", null)", false, ObjectUtils.sameContent("x", null));
            check("sameContent(null, \"x\")", false, ObjectUtils.sameContent(null, "x"));
            check("sameContent(Integer 7, Integer 7)", true, ObjectUtils.sameContent(Integer.valueOf(7), Integer.valueOf(7)));
            check("classNameOf(\"abc\")", "String", ObjectUtils.classNameOf("abc"));
            check("classNameOf(42)", "Integer", ObjectUtils.classNameOf(42));
            check("classNameOf(3.5)", "Double", ObjectUtils.classNameOf(3.5));
            check("classNameOf(null)", "null", ObjectUtils.classNameOf(null));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

