public class ObjectUtils {

    public static boolean sameContent(Object a, Object b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        return a.equals(b);
    }

    public static String classNameOf(Object o) {
        if (o == null) {
            return "null";
        }
        return o.getClass().getSimpleName();
    }
}
